import { normalizeRanges } from './normalize-ranges.mjs';

function assertRangesArray(ranges, name) {
  if (!Array.isArray(ranges)) {
    throw new TypeError(`${name} must be an array`);
  }
}

function validateInterval(member) {
  if (!Array.isArray(member) || member.length !== 2) {
    throw new TypeError('Each range must be an array of two numbers');
  }
  const start = member[0];
  const end = member[1];
  if (typeof start !== 'number' || typeof end !== 'number') {
    throw new TypeError('Range endpoints must be numbers');
  }
  if (!Number.isFinite(start) || !Number.isFinite(end)) {
    throw new TypeError('Range endpoints must be finite numbers');
  }
  if (start > end) {
    throw new RangeError('Range start must not exceed end');
  }
}

function validateAll(ranges, name) {
  assertRangesArray(ranges, name);
  for (const member of ranges) {
    validateInterval(member);
  }
}

function subtractInterval([bs, be], removed) {
  let parts = [[bs, be]];
  for (const [rs, re] of removed) {
    const next = [];
    for (const [ps, pe] of parts) {
      if (re <= ps || rs >= pe) {
        next.push([ps, pe]);
      } else {
        if (rs > ps) {
          next.push([ps, rs]);
        }
        if (re < pe) {
          next.push([re, pe]);
        }
      }
    }
    parts = next;
  }
  return parts.filter(([s, e]) => s < e);
}

export function subtractRanges(base, removed) {
  validateAll(base, 'base');
  validateAll(removed, 'removed');

  const normalizedBase = normalizeRanges(base);
  const normalizedRemoved = normalizeRanges(removed);

  const result = [];
  for (const interval of normalizedBase) {
    const pieces = subtractInterval(interval, normalizedRemoved);
    for (const piece of pieces) {
      result.push([piece[0], piece[1]]);
    }
  }

  return result;
}

